      const recorded = await saveFailure(
        "test",
        tested,
        attempt + 1,
        attempt >= 2 ? "claude-sonnet-5-5" : "claude-haiku-5-5",
      );
      if (!passed(recorded)) return recorded;
      if (unavailable(tested)) break;
      continue;
    }
    const gate = await coordinate("close-task", task, {
      review,
      verification: tested,
      round: attempt + 1,
    });
    if (!passed(gate)) {
      const recorded = await saveFailure(
        "test",
        gate,
        attempt + 1,
        "claude-sonnet-5-5",
      );
      if (!passed(recorded)) return recorded;
