    "CONTINUE_PARENT: burst ended; persist handoff and relaunch from state under /goal. No completion or requirement reduction.",
  findings: [],
  snapshot: {
    ...handoff.snapshot,
    next: "REOBSERVE_AND_LAUNCH",
    run_id: input.run_id,
    attempt_id: input.attempt_id,
  },
};

